package blockbranch.client.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import blockbranch.realistic.*;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.client.gui.screens.TitleScreen;
/** Actual native bodies in an isolated preview copy. Only the two known QA repairs are reset for clean photographs; qualification saves retain them. */
public final class NativeHutIglooView {
 private static boolean opened,saving;private static volatile boolean posed;private static volatile int view;private static int settled;private static long began;private static volatile BlockPos anchor;private static final List<Object> records=new ArrayList<>();
 private static Path dir(){return Path.of(System.getProperty("blockbranch.nativeBodiesViewDir"));}
 public static void register(){
  ServerTickEvents.END_SERVER_TICK.register(server->{if(server.isDedicatedServer()||posed||server.getPlayerList().getPlayers().isEmpty())return;try{
   var player=server.getPlayerList().getPlayers().getFirst();var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var random=level.getChunkSource().randomState();boolean hut=view<2;BlockPos at=hut?g.wetlandHuts(random).forStart(368456>>4,520216>>4).orElseThrow().center():g.snowShelters(random).forStart(322872>>4,-1236360>>4).orElseThrow().center();var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(hut?net.minecraft.world.level.levelgen.structure.BuiltinStructures.SWAMP_HUT:net.minecraft.world.level.levelgen.structure.BuiltinStructures.IGLOO);var start=level.structureManager().getStartForStructure(holder.value(),level.getChunk(at.getX()>>4,at.getZ()>>4));if(start==null||!start.isValid())throw new AssertionError("Actual native start");var commands=server.getCommands();var source=server.createCommandSourceStack();commands.performPrefixedCommand(source,"time set 6000");commands.performPrefixedCommand(source,"weather clear");commands.performPrefixedCommand(source,"gamemode creative "+player.getName().getString());player.getAbilities().flying=true;player.onUpdateAbilities();BlockPos camera,aim;
   if(hut){var piece=(WetlandHutAccess)start.getPieces().getFirst();if(view==0){var edit=piece.blockbranch$local(1,2,2);if(level.getBlockState(edit).is(net.minecraft.world.level.block.Blocks.OAK_PLANKS))level.setBlock(edit,net.minecraft.world.level.block.Blocks.OAK_LOG.defaultBlockState(),3);}camera=view==0?piece.blockbranch$local(-8,6,-10):piece.blockbranch$local(14,5,14);aim=piece.blockbranch$local(3,3,4);anchor=piece.blockbranch$local(3,2,4);if(view==0)open(player,level,piece.blockbranch$local(3,2,6));}
   else{var top=start.getPieces().stream().filter(v->((SnowShelterAccess)v).blockbranch$shelterTop()).findFirst().orElseThrow();var piece=(SnowShelterAccess)top;anchor=piece.blockbranch$local(3,2,4);
    if(view==2){var edit=piece.blockbranch$local(0,1,3);if(level.getBlockState(edit).is(net.minecraft.world.level.block.Blocks.OAK_PLANKS))level.setBlock(edit,net.minecraft.world.level.block.Blocks.SNOW_BLOCK.defaultBlockState(),3);camera=piece.blockbranch$local(-9,5,-10);aim=piece.blockbranch$local(3,2,4);open(player,level,piece.blockbranch$local(1,1,3));open(player,level,piece.blockbranch$local(1,1,5));}
    else if(view==3){camera=piece.blockbranch$local(3,1,2);aim=piece.blockbranch$local(3,1,6);}
    else{var bottom=(SnowShelterAccess)start.getPieces().stream().min(Comparator.comparingInt(v->v.getBoundingBox().minY())).orElseThrow();camera=bottom.blockbranch$local(3,1,7);aim=bottom.blockbranch$local(3,2,2);anchor=aim;}
   }
   double x=camera.getX()+.5,y=camera.getY(),z=camera.getZ()+.5,dx=aim.getX()+.5-x,dz=aim.getZ()+.5-z,dy=aim.getY()+.5-(y+player.getEyeHeight());double yaw=Math.toDegrees(Math.atan2(-dx,dz)),pitch=Math.toDegrees(Math.atan2(-dy,Math.hypot(dx,dz)));commands.performPrefixedCommand(source,"tp "+player.getName().getString()+" "+x+" "+y+" "+z+" "+yaw+" "+pitch);records.add(Map.of("view",view,"camera",camera.toShortString(),"structure",hut?"native swamp hut":"native igloo","pieces",start.getPieces().size()));blockbranch.Blockbranch.LOGGER.info("NATIVE_BODIES_VIEW_POSED {}",view);posed=true;
  }catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("NATIVE_BODIES_VIEW_FAIL",t);try{Files.writeString(dir().resolve("result.txt"),"FAIL "+t);}catch(Exception ignored){}}});
  ClientTickEvents.END_CLIENT_TICK.register(client->{try{
   if(opened&&System.nanoTime()-began>600_000_000_000L){Files.writeString(dir().resolve("result.txt"),"FAIL native view timeout");client.stop();return;}if(!opened&&client.gui.screen() instanceof TitleScreen){opened=true;began=System.nanoTime();client.createWorldOpenFlows().openWorld("NativeBodiesReview",()->client.gui.setScreen(new TitleScreen()));return;}if(Files.exists(dir().resolve("result.txt"))){client.stop();return;}if(!posed||client.level==null||client.player==null||saving)return;client.options.fov().set(view==3?80:view==4?75:55);if(!client.gui.hud.isHidden())client.gui.hud.toggle();client.gui.toastManager().clear();var area=client.levelRenderer.viewArea();if(area==null)return;boolean ready=false;for(int dy:new int[]{-16,0,16}){var section=area.getRenderSectionAt(anchor.offset(0,dy,0));ready|=section!=null&&section.getSectionMesh().hasRenderableLayers();}if(!ready){settled=0;return;}if(++settled<(view==0||view==2?180:100))return;saving=true;
   String file=new String[]{"native-swamp-hut-front.png","native-swamp-hut-rear.png","native-igloo-exterior.png","native-igloo-interior.png","native-igloo-basement.png"}[view];net.minecraft.client.Screenshot.grab(client.gameDirectory,file,client.gameRenderer.mainRenderTarget(),1,message->client.execute(()->{try{if(view<4){view++;posed=false;saving=false;settled=0;}else{Files.writeString(dir().resolve("views.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(records));Files.writeString(dir().resolve("result.txt"),"PASS native bodies, furnishings interactions and basement views");client.stop();}}catch(Exception e){throw new RuntimeException(e);}}));
  }catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("NATIVE_BODIES_VIEW_CLIENT_FAIL",t);try{Files.writeString(dir().resolve("result.txt"),"FAIL "+t);}catch(Exception ignored){}client.stop();}});
 }
 private static void open(net.minecraft.server.level.ServerPlayer p,net.minecraft.server.level.ServerLevel level,BlockPos at){p.setPos(at.getX()+1.5,at.getY(),at.getZ()+.5);p.gameMode.useItemOn(p,level,p.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(at),Direction.UP,at,false));if(p.containerMenu==p.inventoryMenu)throw new AssertionError("Native furnishing interaction "+at);p.closeContainer();}
}
